bxDrill('cellcycle', 'c3', 'C3', 'cell', {lab:"Label the cycle|Légender le cycle|Zyklus beschriften", order:"Order & checkpoints|Ordre et points de contrôle|Reihenfolge & Kontrollpunkte", whatif:"What if…|Et si…|Was wäre wenn…"}, C3BANK);

/* ---------- C4 mitosis & meiosis drawings ---------- */
function mitX(x, y, c, big, rot){ const L = big ? 7 : 4.6, w = 2.6; return `<g class="${c}" transform="rotate(${rot || 0} ${x} ${y})"><line x1="${x - w}" y1="${y - L}" x2="${x + w}" y2="${y + L}"/><line x1="${x + w}" y1="${y - L}" x2="${x - w}" y2="${y + L}"/></g>`; }
function mitI(x, y, c, big, dir){ const L = big ? 7 : 4.6; if (!dir) return `<g class="${c}"><line x1="${x}" y1="${y - L}" x2="${x}" y2="${y + L}"/></g>`;
  return `<g class="${c}"><path d="M${x - dir*4} ${y - L}L${x} ${y}L${x - dir*4} ${y + L}"/></g>`; }
function mitSp(px, pts){ return pts.map(p => `<line class="sp" x1="${px[0]}" y1="${px[1]}" x2="${p[0]}" y2="${p[1]}"/>`).join(''); }
const MIT = {
  int:() => `<ellipse class="cell" cx="60" cy="45" rx="52" ry="38"/><circle class="nuc" cx="58" cy="45" r="22"/><path class="chro" d="M46 40q4 -6 8 0t8 0M50 50q4 6 8 0t8 0M52 36q3 -3 6 0"/><circle class="pole" cx="92" cy="22" r="2.5"/>`,
  pro:() => `<ellipse class="cell" cx="60" cy="45" rx="52" ry="38"/><circle class="nuc dash" cx="60" cy="45" r="24"/>${mitX(50, 38, 'cm', 1, 20)}${mitX(68, 40, 'cp', 1, -15)}${mitX(54, 55, 'cm', 0, 40)}${mitX(70, 56, 'cp', 0)}<circle class="pole" cx="26" cy="30" r="2.5"/><circle class="pole" cx="94" cy="30" r="2.5"/>`,
  prom:() => `<ellipse class="cell" cx="60" cy="45" rx="52" ry="38"/><path class="nfrag" d="M38 30q4 -6 10 -8M80 62q-4 6 -10 8M36 60q-2 -4 -2 -8"/>${mitSp([12, 45], [[48, 33], [57, 56]])}${mitSp([108, 45], [[70, 38], [72, 58]])}${mitX(48, 33, 'cm', 1, 30)}${mitX(70, 38, 'cp', 1, -25)}${mitX(57, 56, 'cm', 0, 15)}${mitX(72, 58, 'cp', 0, 50)}<circle class="pole" cx="12" cy="45" r="2.5"/><circle class="pole" cx="108" cy="45" r="2.5"/>`,
  meta:() => { const ys = [22, 36, 54, 68]; return `<ellipse class="cell" cx="60" cy="45" rx="52" ry="38"/>${mitSp([12, 45], ys.map(y => [60, y]))}${mitSp([108, 45], ys.map(y => [60, y]))}${mitX(60, 22, 'cm', 1, 90)}${mitX(60, 36, 'cp', 1, 90)}${mitX(60, 54, 'cm', 0, 90)}${mitX(60, 68, 'cp', 0, 90)}<line class="plate" x1="60" y1="12" x2="60" y2="78"/><circle class="pole" cx="12" cy="45" r="2.5"/><circle class="pole" cx="108" cy="45" r="2.5"/>`; },
  ana:() => { const ys = [26, 38, 52, 64]; return `<ellipse class="cell" cx="60" cy="45" rx="54" ry="36"/>${mitSp([10, 45], ys.map(y => [36, y]))}${mitSp([110, 45], ys.map(y => [84, y]))}${ys.map((y, i) => mitI(36, y, i % 2 ? 'cp' : 'cm', i < 2, -1) + mitI(84, y, i % 2 ? 'cp' : 'cm', i < 2, 1)).join('')}<circle class="pole" cx="10" cy="45" r="2.5"/><circle class="pole" cx="110" cy="45" r="2.5"/>`; },
  telo:() => `<path class="cell" d="M60 22C40 6 6 14 6 45S40 84 60 68C80 84 114 76 114 45S80 6 60 22Z"/><circle class="nuc" cx="32" cy="45" r="15"/><circle class="nuc" cx="88" cy="45" r="15"/>${mitI(26, 42, 'cm', 1)}${mitI(32, 40, 'cp', 1)}${mitI(37, 48, 'cm', 0)}${mitI(30, 51, 'cp', 0)}${mitI(83, 42, 'cm', 1)}${mitI(89, 40, 'cp', 1)}${mitI(94, 48, 'cm', 0)}${mitI(87, 51, 'cp', 0)}`,
  cyto:() => `<ellipse class="cell" cx="30" cy="45" rx="26" ry="30"/><ellipse class="cell" cx="90" cy="45" rx="26" ry="30"/><circle class="nuc" cx="30" cy="45" r="12"/><circle class="nuc" cx="90" cy="45" r="12"/><path class="chro" d="M24 44q3 -4 6 0t6 0M84 44q3 -4 6 0t6 0"/>`,
  pro1:() => `<ellipse class="cell" cx="60" cy="45" rx="52" ry="38"/><circle class="nuc dash" cx="60" cy="45" r="25"/>${mitX(50, 40, 'cm', 1, 10)}${mitX(56, 40, 'cp', 1, 10)}<path class="cross" d="M48 46l10 -10"/>${mitX(66, 54, 'cm', 0, -20)}${mitX(71, 52, 'cp', 0, -20)}`,
  meta1:() => `<ellipse class="cell" cx="60" cy="45" rx="52" ry="38"/>${mitSp([12, 45], [[54, 30], [54, 58]])}${mitSp([108, 45], [[66, 30], [66, 58]])}${mitX(54, 30, 'cm', 1)}${mitX(66, 30, 'cp', 1)}${mitX(54, 58, 'cp', 0)}${mitX(66, 58, 'cm', 0)}<line class="plate" x1="60" y1="12" x2="60" y2="78"/><circle class="pole" cx="12" cy="45" r="2.5"/><circle class="pole" cx="108" cy="45" r="2.5"/>`,
  ana1:() => `<ellipse class="cell" cx="60" cy="45" rx="54" ry="36"/>${mitSp([10, 45], [[34, 32], [36, 56]])}${mitSp([110, 45], [[86, 32], [84, 56]])}${mitX(34, 32, 'cm', 1)}${mitX(36, 56, 'cp', 0)}${mitX(86, 32, 'cp', 1)}${mitX(84, 56, 'cm', 0)}<circle class="pole" cx="10" cy="45" r="2.5"/><circle class="pole" cx="110" cy="45" r="2.5"/>`,
  telo1:() => `<ellipse class="cell" cx="30" cy="45" rx="26" ry="30"/><ellipse class="cell" cx="90" cy="45" rx="26" ry="30"/>${mitX(26, 38, 'cm', 1)}${mitX(34, 54, 'cp', 0)}${mitX(86, 38, 'cp', 1)}${mitX(94, 54, 'cm', 0)}`,
  meta2:() => `<ellipse class="cell" cx="60" cy="45" rx="40" ry="32"/>${mitSp([22, 45], [[60, 34], [60, 56]])}${mitSp([98, 45], [[60, 34], [60, 56]])}${mitX(60, 34, 'cm', 1, 90)}${mitX(60, 56, 'cp', 0, 90)}<line class="plate" x1="60" y1="18" x2="60" y2="72"/><circle class="pole" cx="22" cy="45" r="2.5"/><circle class="pole" cx="98" cy="45" r="2.5"/>`,
  ana2:() => `<ellipse class="cell" cx="60" cy="45" rx="44" ry="30"/>${mitSp([18, 45], [[42, 36], [42, 54]])}${mitSp([102, 45], [[78, 36], [78, 54]])}${mitI(42, 36, 'cm', 1, -1)}${mitI(42, 54, 'cp', 0, -1)}${mitI(78, 36, 'cm', 1, 1)}${mitI(78, 54, 'cp', 0, 1)}<circle class="pole" cx="18" cy="45" r="2.5"/><circle class="pole" cx="102" cy="45" r="2.5"/>`,
  telo2:() => [[22, 24], [58, 24], [22, 66], [58, 66]].map((p, i) => `<ellipse class="cell" cx="${p[0] + 20}" cy="${p[1]}" rx="17" ry="17"/>${mitI(p[0] + 16, p[1], i % 2 ? 'cp' : 'cm', 1)}${mitI(p[0] + 24, p[1], i < 2 ? 'cp' : 'cm', 0)}`).join('')
};
SXF.mit = o => `<svg class="sxmit${o.big ? ' big' : ''}" viewBox="0 0 120 90" role="img" aria-hidden="${o.big ? 'false' : 'true'}">${MIT[o.p]()}</svg>`;
const MITN = {int:"Interphase|Interphase|Interphase", pro:"Prophase|Prophase|Prophase", prom:"Prometaphase|Prométaphase|Prometaphase", meta:"Metaphase|Métaphase|Metaphase", ana:"Anaphase|Anaphase|Anaphase", telo:"Telophase|Télophase|Telophase", cyto:"Cytokinesis (two daughter cells)|Cytocinèse (deux cellules filles)|Zytokinese (zwei Tochterzellen)",
  pro1:"Prophase I (bivalents, crossing-over)|Prophase I (bivalents, crossing-over)|Prophase I (Bivalente, Crossing-over)", meta1:"Metaphase I (pairs on the plate)|Métaphase I (paires sur la plaque)|Metaphase I (Paare in der Platte)", ana1:"Anaphase I (homologues separate)|Anaphase I (les homologues se séparent)|Anaphase I (Homologe trennen sich)", telo1:"Telophase I (two haploid cells)|Télophase I (deux cellules haploïdes)|Telophase I (zwei haploide Zellen)",
  meta2:"Metaphase II|Métaphase II|Metaphase II", ana2:"Anaphase II (chromatids separate)|Anaphase II (les chromatides se séparent)|Anaphase II (Chromatiden trennen sich)", telo2:"Telophase II (four haploid cells)|Télophase II (quatre cellules haploïdes)|Telophase II (vier haploide Zellen)"};
